import {getTutorialWorldFocus} from './tutorial.mjs';
const app=document.querySelector('#app'),header=document.querySelector('#header');
let state;try{state=loadState(localStorage)}catch{state=newState()}
let screen='home',engine=null,paused=false,hud=null,fleetSlot=0,treeBranch='main',artifactSlot=0,lesson=null,lastSnapshot=null;
let selectedDifficulty=state.profile.difficulty||1;let mainSkillSelection='main-sight';
const performanceEnabled=new URLSearchParams(location.search).get('perf')==='1';let flightPerformance=null;
let muted=false;try{muted=localStorage.getItem('emberwing-muted')==='true'}catch{}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Shared original icons are inserted here during source assembly.

const iconPaths={
 flame:'<path d="M12 2c1 6 7 6 7 12a7 7 0 0 1-14 0c0-3 2-5 4-7-1 4 0 6 2 7-2-5 1-8 1-12Z"/><path d="M12 12c0 3 3 3 3 6a3 3 0 0 1-6 0c0-2 2-3 3-6Z"/>',
 wing:'<path d="M9 3h6v3h3v6h3v6h-3v3H6v-3H3v-6h3V6h3Z"/><path d="M9 12v3m6-3v3"/>',
 route:'<path d="M6 20V9a4 4 0 0 1 4-4h8M6 14h8a4 4 0 0 1 4 4v2"/><circle cx="6" cy="20" r="2"/><path d="m15 2 3 3-3 3"/><circle cx="18" cy="20" r="2"/>',
 cards:'<rect x="7" y="3" width="13" height="17" rx="2"/><path d="m4 5-2 1 3 16 11-2M13.5 7 16 11l-2.5 4L11 11l2.5-4Z"/>',
 ember:'<path d="m12 2 6 8-6 12-6-12 6-8Z"/><path d="M6 10h12m-6-8v20"/>',
 arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',
 star:'<path d="m12 2 2.7 6.3 6.8.7-5.1 4.5 1.5 6.5-5.9-3.5L6.1 20l1.5-6.5L2.5 9l6.8-.7L12 2Z"/>',
 shield:'<path d="m12 2 8 3v6c0 5-4 8-8 11-4-3-8-6-8-11V5l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 wisp:'<path d="M12 3c-5 4-8 7-8 11a8 8 0 0 0 16 0c0-3-2-6-5-8 1 4-1 6-3 7 1-4 1-7 0-10Z"/><circle cx="10" cy="15" r=".7"/><circle cx="15" cy="15" r=".7"/>',
 wind:'<path d="M3 8h11a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M5 17h6a2 2 0 1 1-2 2"/>',
 leaf:'<path d="M20 3C7 2 2 7 4 15c8 5 16 0 16-12Z"/><path d="M3 21 17 7M8 16l1-7m4 2h5"/>',
 ruins:'<path d="M3 21h18M4 7h16M7 7v14m10-14v14M3 7l9-5 9 5M5 11h4m6 0h4"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 sound:'<path d="m11 4-6 5H2v6h3l6 5V4Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 mute:'<path d="m11 4-6 5H2v6h3l6 5V4Zm5 5 5 6m0-6-5 6"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 moon:'<path d="M20.5 14A9 9 0 0 1 10 3a9 9 0 1 0 10.5 11Z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 tune:'<path d="M3 6h18M3 12h18M3 18h18M8 3v6m8 0v6M9 15v6"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>'
};
function icon(name,cls=''){const k=({'✧':'wisp','✦':'sun','◈':'ember','ϟ':'wind','⌄':'wing','⌃':'wing','»':'wind','◇':'flame','♢':'wind','≈':'wind','♨':'flame','♡':'flame',boost:'flame',survival:'wisp',collection:'wisp',mobility:'wing',spirit:'wisp',ash:'flame',speed:'wind',phoenix:'flame',rebirth:'sun',control:'wing'}[String(name).toLowerCase()]||name);return `<svg class="ico ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.star}</svg>`}

iconPaths.ember='<circle cx="8" cy="8" r="3"/><circle cx="16" cy="11" r="3"/><circle cx="10" cy="17" r="3"/>';
iconPaths.flame='<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3" fill="currentColor"/>';
const allRoles=()=>Object.values(COMPANION_ABILITIES);
const runLength=(r=state.run)=>r?.map?.length||7;
const mapHeight=(r=state.run)=>runLength(r)*160+225;
const roleFleet=()=>state.run&&state.run.phase!=='ended'?state.run.companions||[state.run.companionRole]:state.settings.companions||['collector'];
const artifactById=id=>ARTIFACTS[id]||Object.values(ARTIFACTS).find(a=>a.id===id);
function persist(){try{saveState(state,localStorage)}catch{}}
function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function menuButton(){return `<button class="game-menu-trigger" data-action="menu" aria-label="Game menu${screen==='flight'?', pause flight':''}">${icon('tune')}<span>MENU</span></button>`}
function renderHeader(){const inside=screen!=='home'&&state.run&&state.run.phase!=='ended';header.innerHTML=`<div class="game-top-left">${screen==='home'?'<span class="header-wisp">W</span>':`<button class="game-round back-icon" data-action="${['briefing','support'].includes(screen)?'back-route':'exit-menu'}" aria-label="${['briefing','support'].includes(screen)?'Back to route':'Exit to menu'}">${icon('arrow')}</button>`}</div><div class="header-end">${inside?`<button class="bank saved-wallet-bank ember-wallet" data-action="skills" aria-label="Run build and Embers"><span>${pickupArtSvg('embers')}</span><b>${Math.floor(getSkillWallet(state).embers||0)}</b><small>RUN EMBERS</small></button>`:''}${menuButton()}</div>`}
function destroyFlight(){engine?.destroy();engine=null;hud=null;paused=false;document.body.classList.remove('playing');hideLesson()}
function render(view=screen){screen=view;document.body.dataset.screen=screen;document.body.dataset.companionRole=normalizeCompanionRole(roleFleet()[0]);document.body.classList.toggle('playing',screen==='flight');renderHeader();const views={home:renderHome,map:renderMap,briefing:renderBriefing,support:renderSupport,retry:renderRetry,'map-clear':renderMapClear,result:renderResult};app.innerHTML=(views[screen]||renderHome)();if(screen==='map')drawMap();requestAnimationFrame(()=>guideScreen(screen))}
function goToRun(){const r=state.run;if(!r)return render('home');if(r.phase==='ended'){settleCheckpoint(state);bankRun(state);persist();render('result')}else if(r.phase==='map-clear'){settleCheckpoint(state);persist();render('map-clear')}else render(({map:'map',briefing:'briefing',support:'support',retry:'retry'}[r.phase])||'map')}
function beginRun(replace=false){if(state.run&&state.run.phase!=='ended'&&!replace)return goToRun();closeSheet();destroyFlight();if(state.run?.isTutorial)leaveTutorial(state);if(state.run&&state.run.phase!=='ended')abandonRun(state);state.run=createRun(state.settings.testOverride?{...state.profile,difficulty:Math.max(6,state.profile.difficulty||1)}:state.profile,undefined,selectedDifficulty);if(state.settings.testOverride){setTestOverride(state,true);setCompanions(state.run,[getTestStarterCompanion(state)])};fleetSlot=0;treeBranch='main';mainSkillSelection='main-sight';persist();goToRun();if(canChooseStartingSkill(state.run))showSkills('main')}
function requestNewGame(){if(!state.run||state.run.phase==='ended')return beginRun();pauseFlight();openSheet(`<h2>Start a new game?</h2><p class="run-pause-note">This abandons your current three-map run. Its skills, Embers and companion slots reset. Permanent unlocks and recovered artifacts stay.</p><div class="run-pause-actions"><button class="secondary" data-action="close-sheet">Keep current run</button><button class="primary" data-action="confirm-new-game">Abandon & start new</button></div>`,'run-confirm-sheet')}
function exitToMenu(){closeSheet();if(state.run?.isTutorial)return exitTutorial();suspendRun(state);destroyFlight();persist();render('home')}
function requestAbandon(){if(state.run?.isTutorial)return exitTutorial();pauseFlight();openSheet(`<h2>Abandon this run?</h2><p class="run-pause-note">Your run skills and unspent Embers are lost. Permanent unlocks and recovered artifacts stay. To continue later, use Exit to Menu instead.</p><div class="run-pause-actions"><button class="secondary" data-action="close-sheet">Keep playing</button><button class="primary" data-action="confirm-abandon">Abandon run</button></div>`,'run-confirm-sheet')}
function showUnlocks(){pauseFlight();const unlocked=state.profile.difficulty||1;openSheet(`<h2>Companion unlocks</h2><p class="run-pause-note">Clear all three maps to unlock the next ascension and its companion. Choose your starter at the beginning of a run; change at rests.</p><div class="unlock-roster">${allRoles().map(role=>`<article>${companionArtSvg(role.id)}<div><strong>${esc(role.name)}</strong><p>${role.unlockDifficulty<=unlocked?'UNLOCKED':`CLEAR ASCENSION ${role.unlockDifficulty-1}`}</p><small>${esc(role.description)}</small></div></article>`).join('')}</div><button class="primary" data-action="close-sheet">Back</button>`,'unlock-sheet')}
function enterTutorial(){closeSheet();if(engine){pauseFlight();suspendRun(state)}if(!startTutorial(state))return;destroyFlight();persist();goToRun()}
function exitTutorial(){if(!leaveTutorial(state))return;closeSheet();destroyFlight();persist();render('home')}
function endRun(){closeSheet();destroyFlight();abandonRun(state);state.run=null;persist();render('home')}
function backRoute(){const r=state.run;if(!r||r.attemptActive||!['support','briefing'].includes(r.phase))return;r.path=r.path.filter(id=>id!==r.current?.id);r.current=null;r.phase='map';persist();goToRun()}
function objectiveStrip(text,symbol='route'){return `<div class="objective-strip">${icon(symbol)}<span>${esc(text)}</span></div>`}
function nodeLocation(n){return resolveLevelIdentity(n?.levelId,n?.terrain||'ruins',`${state.run?.seed}-${n?.id}`)}
function currentAscent(n=state.run?.current){return getAscentInfo(n||{row:state.run?.step||0,difficulty:state.run?.difficulty||1},!!state.run?.isTutorial)}
function fleetArt(ids=roleFleet(),cls=''){return `<div class="fleet-orbs ${cls}">${ids.map(id=>`<span title="${esc(getCompanionAbility(id).name)}">${companionArtSvg(id)}</span>`).join('')}</div>`}
function prepOpen(){return !!state.run&&state.run.phase!=='ended'&&canChangeCompanion(state.run)}
function reservePanel(){return storedGlowPanelMarkup(getAfterglowState(state),{draw:true})}
function tutorialCheckpoint(){return state.run?.isTutorial?`<div class="tutorial-checkpoint"><span>FIRST LIGHT</span><button data-action="skip-practice">Skip practice ${icon('arrow')}</button></div>`:''}
function artifactArt(id){return artifactIcon(id)}
function artifactsRevealed(){return !state.run?.isTutorial&&(state.run?.testMode||state.profile.afterglowUnlocked===true||(state.profile.ownedArtifacts||[]).length>0)}
function artifactSlots(){if(!artifactsRevealed())return '';const ids=state.run&&state.run.phase!=='ended'?state.run.artifacts||[]:state.profile.equippedArtifacts||[];return `<div class="artifact-slots" aria-label="Three artifact slots">${[0,1,2].map(i=>`<button class="artifact-slot ${ids[i]?'filled':''}" data-action="artifacts" data-slot="${i}" aria-label="${ids[i]?esc(artifactById(ids[i])?.name):'Empty artifact slot'}">${ids[i]?artifactArt(ids[i]):'<span>+</span>'}</button>`).join('')}</div>`}
function renderHome(){return homeMenuMarkup({profile:state.profile,run:state.run,selectedDifficulty,testOverride:state.settings.testOverride,testStarterCompanion:getTestStarterCompanion(state)})+testControls()}
function forecastMarkup(n){if(state.run?.isTutorial)return '';const f=getRouteForecast(state.run,n)||{};return `<div class="route-consequences ${!f.restReachable?'rest-scarce':''}"><div><b>${mapStopIconMarkup('rest')}${f.nextRestDistance===0?'REST HERE':f.restReachable?`REST WITHIN ${f.nextRestDistance} STOPS`:'NO REST AHEAD'}</b><span>${n.type==='support'?(n.kind==='camp'?'RECOVERY · TRAINING':'A TRADE, NO TRAINING'):n.elite?'ELITE · GREATER REWARD':esc(n.fuelPreview||'CONSERVE GLOW')}</span></div><div class="forecast-path">${(f.nextStops||[]).slice(0,3).map(stop=>`<span title="${esc(stop.name)}">${mapStopIconMarkup(stop)}<small>${esc(getMapStopInfo(stop).label)}</small></span>`).join('<i>OR</i>')}</div></div>`}
function renderMap(){const r=state.run;return `<section class="game-map-screen map-v2 minimal-map">${campaignStrip(r,state.profile)}<div class="map-status-strip"><span class="map-stop-counter">STOP ${Math.min(r.step+1,r.map.length)}/${r.map.length}</span>${livesMarkup(r)}<span class="glow-label">${icon('flame')}${Math.round(r.flame)}% GLOW</span></div>${tutorialCheckpoint()}${!r.isTutorial&&r.mapIndex===0&&r.step===0&&!r.path.length?`<button class="starter-companion" data-action="companions">${fleetArt()}<span>CHOOSE STARTER COMPANION</span>${icon('arrow')}</button>`:''}${canChooseStartingSkill(r)?'<button class="starter-companion" data-action="bond-tree">CHOOSE YOUR FREE STARTING GIFT</button>':''}<button class="checkpoint-skill-button" data-action="skills">${icon('route')} SKILL TREE</button><div class="map-top-guide">${objectiveStrip(r.restReady?'REST PREP · train or change companions':'Choose your route · plan your next rest')}<button class="map-key-button" data-action="map-key">${icon('info')}KEY</button></div><div class="map-atlas-frame"><div class="game-map-viewport" id="map-viewport"><svg id="journey-map" class="game-world-map" viewBox="0 0 390 ${mapHeight(r)}"></svg></div></div><div class="map-build-dock">${r.restReady?`<div class="rest-services"><button data-action="skills">${icon('route')}SKILL TREE</button><button data-action="companions">${fleetArt()}COMPANIONS</button>${artifactsRevealed()?`<button data-action="artifacts">${icon('star')}ARTIFACTS</button>`:''}</div>`:''}${artifactSlots()}</div></section>`}
function plannedChallengesMarkup(n){if(state.run?.isTutorial||n.boss)return '';const preview=getChallengePreview({...n,stage:n.row});return `<div class="flight-challenge-preview" aria-label="Planned terrain challenges">${preview.patterns.map(pattern=>`<span>${icon(pattern.type==='fuel-pocket'?'flame':pattern.type==='draft-crossing'?'wing':'wisp')}${esc(pattern.name)}</span>`).join('')}</div>`}
function flightCue(snapshot){if(snapshot.completing)return 'PASSAGE CLEARED';if(snapshot.dying)return snapshot.event||'The light scatters…';if(snapshot.resumeRemaining>0)return `RESUMING · ${Math.round((snapshot.resumeScale||.1)*100)}%`;const challenge=snapshot.flightChallenge;if(!challenge)return snapshot.event||'';if(challenge.phase==='warning')return challenge.type==='dark-cave'?'CAVE AHEAD · SIGHT NARROWS':challenge.type==='draft-crossing'?'DRAFT AHEAD · CHOOSE YOUR CROSSING':challenge.pocket?.side==='ceiling'?'FUEL POCKET ABOVE':'FUEL POCKET AHEAD';if(challenge.phase==='active'&&challenge.progress<.2)return challenge.name;return snapshot.event||''}
function renderBriefing(){const r=state.run,n=r.current,loc=nodeLocation(n);return `<section class="center-view compact-briefing ${n.boss?'boss-brief':''}">${campaignStrip(r,state.profile)}${tutorialCheckpoint()}<div class="encounter-art location-art" data-location="${loc.id}">${levelMapPreview(loc)}${n.boss?bossSigil():''}<span class="encounter-badge">${n.boss?'BOSS':n.elite?'ELITE':'FLIGHT'}</span></div><h1>${esc(n.name)}</h1><div class="brief-stats"><span>${livesMarkup(r)}</span><span class="glow-label">${icon('flame')}${Math.round(r.flame)}% GLOW</span><span>${formatFlightDuration(n.duration)}</span></div>${forecastMarkup(n)}${plannedChallengesMarkup(n)}${n.setpiecePreview?`<div class="setpiece-preview">${esc(n.setpiecePreview)}</div>`:''}${reservePanel()}<div class="flight-ready-fleet">${fleetArt()}<span>${roleFleet().map(id=>getCompanionAbility(id).name).join(' + ')}</span></div>${r.flame<21?'<div class="low-glow-warning">LOW GLOW · FIND FUEL EARLY</div>':''}<button class="primary enter-passage" data-action="launch">Enter ${icon('arrow')}</button>${artifactSlots()}</section>`}
function supportValues(effect={}){return [['flame','GLOW'],['embers','EMBERS'],['afterglow','STORED GLOW'],['lives','HEARTS']].filter(([k])=>effect[k]).map(([k,label])=>`<span class="boon-resource-value ${effect[k]<0?'boon-cost':''}">${k==='lives'?lifeHeartSvg():k==='embers'?icon('ember'):k==='afterglow'?reserveIconMarkup():icon('flame')}<b>${k==='flame'?effect[k]>=100?'100%':`${effect[k]>0?'+':''}${effect[k]}%`:`${effect[k]>0?'+':''}${effect[k]}`}</b><small>${label}</small></span>`).join('')}
function renderSupport(){const r=state.run,n=r.current,choices=getSupportChoices(r,state.profile);return `<section class="center-view compact-support">${campaignStrip(r,state.profile)}${tutorialCheckpoint()}<div class="support-symbol">${mapStopIconMarkup(n)}</div><h1>${esc(n.name)}</h1><div class="support-vitals">${livesMarkup(r)}<span class="glow-label">${icon('flame')}${Math.round(r.flame)}% GLOW</span></div>${forecastMarkup(n)}<div class="support-offers">${choices.map((c,i)=>`<button class="route-choice boon-choice" data-action="support" data-index="${i}"><span class="boon-emblem">${c.effect?.lives?lifeHeartSvg():icon(c.effect?.flame?'flame':'ember')}</span><h3>${esc(c.title)}</h3><div class="boon-values">${supportValues(c.effect)}</div><p>${esc(c.description)}</p>${c.effect?.upgrade?`<p class="support-upgrade-effect">${esc(SKILLS[c.effect.upgrade]?.consequence||SKILLS[c.effect.upgrade]?.description||'')}${SKILLS[c.effect.upgrade]?.choiceGroup?' · Commits this path for the run.':''}</p>`:''}</button>`).join('')}</div>${n.kind==='camp'?'<p class="rest-service-note">Choose a boon to open training and companion preparation.</p>':artifactsRevealed()?`<button class="secondary" data-action="artifacts">${icon('star')}Trade artifacts</button>`:''}</section>`}
function renderRetry(){const r=state.run;return `<section class="center-view compact-retry"><div class="retry-fallen">${icon('wisp')}</div><h1>Light lost</h1><div class="retry-level-label">${esc(r.current?.name)}</div><div class="retry-lives">${livesMarkup(r)}</div><button class="primary" data-action="retry">Retry this passage ${icon('arrow')}</button><button class="secondary" data-action="abandon-run">Abandon run</button></section>`}
function renderMapClear(){const r=state.run;return `<section class="center-view compact-result map-clear-screen">${campaignStrip(r,state.profile)}<div class="result-symbol">${icon('route')}</div><h1>Map ${r.mapIndex+1} cleared</h1><p>${esc(r.mapName)}</p><div class="map-clear-carry">${livesMarkup(r)}<span class="glow-label">${icon('flame')}${Math.round(r.flame)}% GLOW</span></div>${fleetArt()}${artifactSlots()}<p class="map-clear-note">Your fuel, lives and build continue.</p><button class="primary" data-action="next-map">MAP ${r.mapIndex+2} ${icon('arrow')}</button></section>`}
function renderResult(){const r=state.run,drop=r.lastFlight?.artifactDrop,role=r.success&&!r.isTutorial?allRoles().find(c=>c.unlockDifficulty===r.difficulty+1):null;return `<section class="center-view compact-result">${campaignStrip(r,state.profile)}<div class="result-symbol">${r.success&&!r.isTutorial?bossSigil():icon('wisp')}</div><h1>${r.isTutorial?'Practice complete':r.success?'Run complete':'Run ended'}</h1><div class="result-stats"><div><strong>${Math.floor(r.securedEmbers||0)}</strong><span>EMBERS EARNED THIS RUN</span></div><div><strong>${r.stats?.flights||0}</strong><span>FLIGHTS</span></div></div>${drop?`<section class="artifact-drop">${drop.duplicate?reserveIconMarkup():artifactArt(typeof drop==='string'?drop:drop.id)}<span>${drop.duplicate?'BOSS REWARD':'PERMANENT BOSS ARTIFACT'}</span><h2>${drop.duplicate?(drop.convertedGlow?`+${drop.convertedGlow} STORED GLOW`:'Reserve full'):esc(artifactById(typeof drop==='string'?drop:drop.id)?.name||'Relic recovered')}</h2><p>${drop.duplicate?esc(drop.message||'All artifacts collected.'):'Mount during your next run.'}</p></section>`:''}${afterglowUnlockMarkup(r)}${role?`<section class="result-companion-unlock">${companionArtSvg(role.id)}<div><span>AVAILABLE FOR YOUR NEXT RUN</span><h2>${esc(role.name)}</h2><p>Ascension ${r.difficulty+1} available</p></div></section>`:''}${r.isTutorial?'<button class="primary" data-action="leave-practice">Back to Menu</button>':`<p class="run-pause-note">Run skills and Embers reset. Permanent unlocks remain.</p><div class="two-actions"><button class="secondary" data-action="exit-menu">Main menu</button><button class="primary" data-action="new-game">New Game ${icon('arrow')}</button></div>`}</section>`}

function closeSheet(){const el=document.querySelector('dialog.game-sheet');if(el){el.close();el.remove()}}
