function showFleet(){if(screen==='home'||!state.run||state.run.phase==='ended')return showUnlocks();pauseFlight();fleetSlot=Math.min(fleetSlot,getCompanionCapacity(state.run&&state.run.phase!=='ended'?state.run:state.profile)-1);openSheet(fleetMarkup(),'companion-sheet')}
function chooseFleet(id){if(screen==='home'||!state.run||state.run.phase==='ended')return;const active=state.run&&state.run.phase!=='ended',source=active?state.run:state.profile,capacity=getCompanionCapacity(source),ids=[...(active?state.run.companions:state.settings.companions||['collector'])];if(engine||!getCompanionUnlock(id,state.profile.difficulty).selectable||active&&!canChangeCompanion(state.run))return;if(ids.includes(id)){if(ids.length>1)ids.splice(ids.indexOf(id),1)}else if(fleetSlot<ids.length)ids[fleetSlot]=id;else if(ids.length<capacity)ids.push(id);else ids[Math.min(fleetSlot,ids.length-1)]=id;const unique=[...new Set(ids)];if(active){if(!setCompanions(state.run,unique))return}else state.settings.companions=unique;persist();if(!engine&&screen!=='home')render(screen);showFleet()}
function artifactsMarkup(){const ids=state.run&&state.run.phase!=='ended'?state.run.artifacts||[]:state.profile.equippedArtifacts||[],owned=state.run?.testMode?Object.keys(ARTIFACTS):state.profile.ownedArtifacts||[],safe=!engine&&(prepOpen()||state.run?.current?.type==='support'),trade=!engine&&(state.run?.current?.type==='support'||state.run?.restReady);return `<h2>ARTIFACTS</h2><p class="artifact-rule">Boss relics · three equipped slots</p><div class="artifact-equip-slots">${[0,1,2].map(i=>`<button class="artifact-slot ${artifactSlot===i?'selected':''}" data-action="artifact-slot" data-index="${i}">${ids[i]?artifactArt(ids[i]):'<b>+</b>'}<small>${i+1}</small></button>`).join('')}</div><div class="artifact-inventory">${owned.length?owned.map(id=>{const a=artifactById(id);return `<article class="artifact-item">${artifactArt(id)}<div><h3>${esc(a?.name||id)}</h3><p>${esc(a?.description||'')}</p><small>${ids.includes(id)?'EQUIPPED':''}</small></div><div><button class="secondary" data-action="equip-artifact" data-id="${id}" ${safe?'':'disabled'}>Mount ${artifactSlot+1}</button><button class="artifact-trade" data-action="sell-artifact" data-id="${id}" ${trade&&!state.run?.testMode?'':'disabled'}>Trade ${icon('ember')}${a?.sellValue||25}</button></div></article>`}).join(''):'<div class="empty-relic">Defeat a boss to recover your first artifact.</div>'}</div><p class="artifact-rule">Mount at camp or rest. Trade at events and shelters.</p><button class="primary" data-action="close-sheet">Done</button>`}
